def apply_compare(ctx):
 P,pages,article,ref,table,section=ctx['P'],ctx['PAGES'],ctx['article'],ctx['ref'],ctx['table'],ctx['section']
 source=[(D['client'],'pokebonk.com — v0.8.63 original client','Inspected October 28, 2026. SINGLE_SOURCE: current rules and encounter prompts; no completed run, measured DPS or boss victory claimed.'),(D['config'],'pokebonk.com — v0.8.63 configuration','Current species, League and passive definitions compare equal to the preceding .62 snapshot. The embedded Play host remains a separate .27 edition.')]
 # Extend original selectors, preserving all established IDs and defaults.
 p=pages[P+'pokemon/'];s=p['html'];s=s.replace('<option value="name">', '<option value="hp">HP: high to low</option><option value="armor">Armor: high to low</option><option value="speed">Speed: high to low</option><option value="physical">Physical: high to low</option><option value="special">Special: high to low</option><option value="name">',1)
 basis='<label>Comparison milestone <select id="comparison-basis"><option value="start">Starting form</option><option value="final">Final listed form</option><option value="grown">Final form + eligible level-44 growth</option></select></label><p class="compare-scope">Sorting and the comparison table use the selected form’s baseline before passive, Lab, items and vitamins. A branch defaults to its first listed final form; change that partner’s selector to choose another.</p>'
 s=s.replace('<section class="collection-controls"',basis+'<section class="collection-controls"',1)
 for x in ROLE['league']:
  opts=''.join(f'<option value="{f["id"]}">{e(f["name"])} — {e(f["at"])}</option>'for f in x['forms'])
