 statuses=sorted({x['status']for x in D['reactions']});types=ROLE['typeChart']['types'];opts=lambda vals:''.join(f'<option value="{v}">{v.title()}</option>'for v in vals)
 checker='<div class="tool"><label>Existing target status <select id="reaction-status">'+opts(statuses)+'</select></label><label>Following hit type <select id="reaction-type">'+opts(types)+'</select></label><label>Existing poison stacks <input id="poison-stacks" type="number" min="1" max="10" value="1"></label><div id="reaction-result" role="status"></div></div>'
 article('reactions','PokeBonk Status Reactions: Conditions & Pair Checker','Check the status before choosing the follow-up hit','Choose a target status and a following attack type to inspect PokeBonk reactions, their consumed conditions and limits, then check your planned kit.','A combat reaction needs a status already on the target and a compatible later hit. This is different from combining moves at Bill’s Machine. Use the checker to identify a possible reaction, then verify that your kit can create its prerequisite.'+ref(1),[('checker','Check a reaction condition',checker+'<p>Source snapshot: original v0.8.63, checked October 28. This checker evaluates one existing status at a time; it does not simulate simultaneous statuses, hit chance, damage or a completed fight.</p>'+ref(1)),('rules','Read the trigger and what gets consumed',table(['Existing status','Following type','Result','Reaction layer','Effect / limit'],rows)+'<p>The 0.25-second gate in the reaction routine is shared by reaction key within the combat instance, not an independent allowance for every enemy. Nightmare and Wet-to-Freeze setup follow separate branches. Other damage layers can apply before or after these factors.</p>'+ref(1)),('plan','Make the prerequisite real','<ol><li>Find a selected move or item that can apply the required status. An attack’s type alone is not proof of its status effect.</li><li>Apply the status first. In the checked hit routine, reaction evaluation precedes the current hit’s own status roll.</li><li>Use a compatible following hit while the status still exists. Boss resistance, status duration and consuming effects can change the opportunity.</li><li>Inspect the resulting behavior in your run. The planner flags potential routes, not a guaranteed proc.</li></ol>'+ref(1)+ref(2)),('distinction','Separate reactions, fusions and type matchups',table(['Task','Use','What it does not establish'],[['Combat reaction','This status checker','Does not fuse two moves or guarantee a status roll.'],['Move fusion','Bill’s Machine recipe finder','A valid recipe is not a combat-status reaction.'],['Type matchup','Type chart calculator','A favorable type does not create a status.']]))],source,[('build-planner/','Check a kit and its fixed modifiers'),('move-fusions/','Find a Bill’s Machine recipe'),('type-chart/','Calculate type matchups')],script='compare.js')
 # Pacts and actual region differences belong in the existing Survival task.
 p=pages[P+'survival/'];t=table(['Pact','Benefit','Cost','Listed repeat limit'],[[e(x['name']),e(x['boon']),e(x['bane']),str(x['max'])]for x in D['pacts']])
 pact=section('pact-reference','Read all nine pact trade-offs',t+'<p>These are the current .63 client definitions, not a promise that every pact is offered at every checkpoint. Choose for the problem your run can handle. A repeat limit is not a recommendation to take that pact to its limit.</p><p>Curse stacking is not always additive: two Horde selections multiply wild amount by 1.25 twice (1.5625×); two Iron selections multiply wild HP by 1.35 twice (1.8225×). Glass applies a 0.8 max-HP factor per pick, while its positive modifiers use the client’s grouped stat rules. Judge benefit and cost separately.</p>'+'__PACT_SOURCE__'+'<p>For an enemy-count problem, Horde or Elite can make pressure worse. For a recovery problem, Thorny reduces healing and Glass reduces the HP margin. These are editorial decision checks based on the stated costs, not tested winning pact sequences.</p>')
 p['html']=p['html'].replace('<section class="sources"',pact+'<section class="sources"',1)
 regions=table(['Region','What to carry into preparation','Related next task'],[['Viridian Forest','Use the existing 15/30/45-minute reference; inspect each pact.','Check League conditions separately from a boss encounter.'],['Rocky Desert','Read its own preparation screen and guardian list; do not rename Forest guardians.','Recheck the region when comparing a Survival record.'],['Storm Coast','Keep the map/region distinction from its Classic Zapdos sanctuary.','Read the Zapdos encounter guide for the Classic shrine.'],['Celestial Glacier','Keep Survival checkpoints distinct from the Classic Articuno arena.','Read the Articuno encounter guide for the Classic shrine.']])
 p['html']=p['html'].replace('<section class="sources"',section('region-scope','Keep Survival and Classic arena mechanics separate',regions+'<p>The source uses region-specific guardian pools for ordinary Survival checkpoints. This page does not claim a completed run through every regional sequence. Classic shrine solutions should not be copied to an endless guardian just because the region name matches.</p>'+'__PACT_SOURCE__')+'<section class="sources"',1)
 # Dedicated boss tasks are source-based decisions; never dress them up as recorded victories.
 bosses=[('zapdos','Zapdos','Storm Coast','Rocky Desert',[['Directed lightning','Find an active rod and guide the targeting toward it.','An inactive rod is not an interchangeable safe spot.'],['Rod charge and discharge','Read the active rod’s charge and use the opening when discharge downs Zapdos.','Keep the active-object state in view; do not assume any rod always protects you.'],['Electrified Sea','Leave the water for a plateau/island or use a jump while responding to the attack.','Remaining in electrified water can punish a stationary damage plan.'],['Supreme Thunder','Follow the prompt into the storm eye or beside an active lightning rod.','A generic distant corner is not the stated safe solution.']]),('articuno','Articuno','Celestial Glacier','Storm Coast',[['Ice armor','Break the lake crystals to remove the armor identified by the encounter prompt.','More damage alone is not the same as solving the armor mechanic.'],['Ice Beam','Use a living column to set up a reflected path toward Articuno.','Positioning and the current beam path matter; this is not a fixed coordinate script.'],['Self-reflected beam','When its own reflected beam freezes it, reposition to use the opening.','The source has a freeze/opening window; we have not timed a completed fight.'],['Sheer Cold','Move to the sectors with a golden edge before they freeze.','React to the shown safe sectors rather than memorizing a static safe tile.']])]
